def _verify(headers, body, secrets, now):
    h = {str(k).lower(): v for k, v in headers.items()}
    sig_header = h.get("corvid-signature")
    event_id = h.get("corvid-event-id")
    if not isinstance(sig_header, str) or not isinstance(event_id, str):
        return False
    ts = []
    sigs = []
    for el in sig_header.split(","):
        el = el.lstrip(" ")
        key, sep, value = el.partition("=")
        if not sep:
            return False
        if key == "t":
            ts.append(value)
        elif key == "v2":
            sigs.append(value)
    if len(ts) != 1 or not (ts[0].isascii() and ts[0].isdigit()):
        return False
    t = int(ts[0])
    if now - t > 300 or t - now > 60:
        return False
    payload = b"v2:" + ts[0].encode() + b":" + event_id.encode() + b":" + bytes(body)
    ok = False
    for secret in secrets:
        if not secret.startswith("whsec_"):
            continue
        try:
            key = base64.b64decode(secret[6:], validate=True)
        except Exception:
            continue
        expected = hmac.new(key, payload, hashlib.sha256).hexdigest()
        for sig in sigs:
            if hmac.compare_digest(sig.encode(), expected.encode()):
                ok = True
    return ok''')
